package app

import (
	"time"

	"charm.land/bubbles/v2/spinner"
	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// blinkHalfPeriod is the blink's half period (D7: 1 Hz). A const: the phase formula
// must not change when a test shortens the chain's interval.
const blinkHalfPeriod = 500 * time.Millisecond

// Intervals are vars so testutil.FastTimers can shorten them.
var (
	animationFastInterval  = spinner.Dot.FPS
	animationBlinkInterval = blinkHalfPeriod
)

// blinkPhase reads the phase off the tick's own time, so every view blinks in step
// whatever the interval the chain currently runs at.
func blinkPhase(t time.Time) bool {
	return (t.UnixMilli()/blinkHalfPeriod.Milliseconds())%2 == 0
}

// cadence returns the interval the animation chain should run at, and false when
// nothing needs it. A running spinner needs the fast interval; a blink alone needs
// the slow one, unless static motion is requested (then the glyph stays steady).
func cadence(running, wantsBlink, static bool) (time.Duration, bool) {
	switch {
	case running:
		return animationFastInterval, true
	case wantsBlink && !static:
		return animationBlinkInterval, true
	default:
		return 0, false
	}
}

// animationState is the one chain that moves anything on a row (D5, renamed D2).
type animationState struct {
	seq      int           // identifies the live chain; a tick from another is dropped
	ticking  bool          // a chain is alive
	interval time.Duration // cadence of the live chain
	frameIdx int
	blinkOn  bool // true whenever no chain runs
}

// animationTickMsg advances the animation. at is the tick's own time, from which
// the blink phase is read.
type animationTickMsg struct {
	seq int
	at  time.Time
}

// animationEvery is tea.Every, a var so tests record the interval and inject the time.
var animationEvery = tea.Every

// animationTick asks for the next tick of chain seq. It is on the clock's
// boundaries (tea.Every) so the blink phase alternates strictly. seq and d are
// captured by value: the Cmd never touches the router (Rule 110).
func animationTick(seq int, d time.Duration) tea.Cmd {
	return animationEvery(d, func(t time.Time) tea.Msg {
		return animationTickMsg{seq: seq, at: t}
	})
}

// animationFrame returns the current bare spinner frame.
func (a *App) animationFrame() string {
	frames := spinner.Dot.Frames
	return frames[a.anim.frameIdx%len(frames)]
}

// frameMsg builds the animation message. It fills both readings of the frame —
// bare for a table cell (Rule 122), styled for a footer (Rule 128) — so the
// two cannot drift and internal/jobs needs to know nothing about styling.
func (a *App) frameMsg() jobs.FrameMsg {
	frame := a.animationFrame()
	return jobs.FrameMsg{
		Frame:         frame,
		RenderedFrame: theme.SpinnerStyle().Render(frame),
		Blink:         a.anim.blinkOn,
	}
}

// sendFrameTo hands the current frame to one view: the view on screen on every
// tick, and a view entering the screen. No resize check: a frame never changes
// a footer's height.
func (a *App) sendFrameTo(target command.ViewType) tea.Cmd {
	view, ok := a.views[target]
	if !ok {
		return nil
	}
	updated, cmd := view.Update(a.frameMsg())
	a.setView(target, updated)
	return cmd
}

// ensureTick starts the chain when something needs one and none is alive, and
// replaces a slower chain by a faster one (a new seq makes the old tick stale).
// It returns nil otherwise, which makes it idempotent within one Update. It is
// the one place a chain is ever started (D5).
func (a *App) ensureTick() tea.Cmd {
	d, ok := a.wantedCadence()
	if !ok || (a.anim.ticking && a.anim.interval <= d) {
		return nil
	}
	a.anim.ticking = true
	a.anim.seq++
	a.anim.interval = d
	return animationTick(a.anim.seq, d)
}

// handleAnimationTick advances the animation, reads the blink phase off the
// tick's own time, hands it to the view on screen, and renews the chain for as
// long as something needs it, at the cadence the need has now (a downgrade from
// fast to slow happens here, without a new seq).
//
// The chain stops by not being renewed. It never stops on an "off" phase: a row
// is left on a steady "on" glyph. The frame only moves while work runs.
func (a *App) handleAnimationTick(msg animationTickMsg) (tea.Model, tea.Cmd) {
	if msg.seq != a.anim.seq {
		return a, nil
	}
	running := a.jobs.Running() > 0
	d, ok := a.wantedCadence()
	if !ok {
		a.anim.ticking = false
		// A blur always hands the view one last pinned frame: the tick that
		// lands after it is the last the view will see for a while.
		if a.anim.blinkOn && !a.suspended() {
			return a, nil
		}
		a.anim.blinkOn = true
		return a, a.sendFrameTo(a.currentView)
	}
	if running {
		a.anim.frameIdx = (a.anim.frameIdx + 1) % len(spinner.Dot.Frames)
	}
	a.anim.blinkOn = a.motionStatic || blinkPhase(msg.at)
	a.anim.interval = d
	return a, tea.Batch(a.sendFrameTo(a.currentView), animationTick(a.anim.seq, d))
}
	// which matches no run.
	Context string
}

// Running counts the runs in the snapshot that have not settled. It saves every
// receiver the same three lines.
func (m ChangedMsg) Running() int {
	return len(Unfinished(m.Runs))
}

// FrameMsg says the animation moved: the spinner frame, the blink phase, or
// both. It carries no snapshot — ChangedMsg is for changes of the registry.
// The router sends it to the view on screen only (DEVDESK-139).
type FrameMsg struct {
	Frame         string // bare, Rule 122 (a cell measures it)
	RenderedFrame string // styled, Rule 128 (a footer takes it)
	Blink         bool   // true = the "on" half of the blink
}

package app

import (
	"strings"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// framesSeen returns every FrameMsg a view was handed, oldest first.
func framesSeen(v *fakeView) []jobs.FrameMsg {
	var out []jobs.FrameMsg
	for _, msg := range v.received {
		if typed, ok := msg.(jobs.FrameMsg); ok {
			out = append(out, typed)
		}
	}
	return out
}

// stubAnimationEvery records the interval of every chain request and returns a
// Cmd that yields the tick at `at` immediately, without sleeping.
func stubAnimationEvery(t *testing.T, at time.Time) *[]time.Duration {
	t.Helper()
	var got []time.Duration
	orig := animationEvery
	animationEvery = func(d time.Duration, fn func(time.Time) tea.Msg) tea.Cmd {
		got = append(got, d)
		return func() tea.Msg { return fn(at) }
	}
	t.Cleanup(func() { animationEvery = orig })
	return &got
}

func TestOnlyOneAnimationChainIsEverAlive(t *testing.T) {
	a := router(t, &fakeView{})
	a.jobs.Start(scanRun("default", "a"))

	if a.ensureTick() == nil {
		t.Fatal("no chain was started for work that is running")
	}
	if second := a.ensureTick(); second != nil {
		t.Error("a second chain was started while the first was alive")
	}
	if !a.anim.ticking {
		t.Error("the router does not know its chain is alive")
	}
}

func TestTheChainStartsAtTheFastInterval(t *testing.T) {
	got := stubAnimationEvery(t, time.UnixMilli(1000))
	a := router(t, &fakeView{})
	a.jobs.Start(scanRun("default", "a"))

	a.ensureTick()

	if len(*got) != 1 || (*got)[0] != animationFastInterval {
		t.Errorf("chain intervals = %v, want one of %v", *got, animationFastInterval)
	}
}

func TestATickFromAnOlderChainIsDropped(t *testing.T) {
	view := &fakeView{}
	a := router(t, view)
	a.jobs.Start(scanRun("default", "a"))
	a.ensureTick()

	before := a.animationFrame()
	_, cmd := a.Update(animationTickMsg{seq: a.anim.seq - 1, at: time.UnixMilli(1000)})

	if a.animationFrame() != before {
		t.Error("a stale tick advanced the frame")
	}
	if cmd != nil {
		t.Error("a stale tick was answered with a command")
	}
	if n := len(framesSeen(view)); n != 0 {
		t.Errorf("a stale tick delivered %d FrameMsg, want 0", n)
	}
}

// A tick sends the frame and nothing else, and only to the view on screen.
func TestATickSendsAFrameAndNoSnapshot(t *testing.T) {
	onScreen, offScreen := &fakeView{}, &fakeView{}
	a := router(t, onScreen)
	a.views[command.ViewWorkspaces] = offScreen
	a.jobs.Start(scanRun("default", "a"))
	a.jobsChanged()

	frames, snaps := len(framesSeen(onScreen)), len(jobsSeen(onScreen))
	offFrames, offSnaps := len(framesSeen(offScreen)), len(jobsSeen(offScreen))

	a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(1000)})

	if got := len(framesSeen(onScreen)); got != frames+1 {
		t.Errorf("the view on screen got %d FrameMsg, want %d", got-frames, 1)
	}
	if got := len(jobsSeen(onScreen)); got != snaps {
		t.Errorf("the view on screen got %d new snapshots from a tick, want 0", got-snaps)
	}
	if got := len(framesSeen(offScreen)); got != offFrames {
		t.Error("a view off screen got a FrameMsg")
	}
	if got := len(jobsSeen(offScreen)); got != offSnaps {
		t.Error("a view off screen got a snapshot from a tick")
	}
}

func TestATickAdvancesTheFrameAndRenewsTheChain(t *testing.T) {
	testutil.FastTimers(t, &animationFastInterval)
	view := &fakeView{}
	a := router(t, view)
	a.jobs.Start(scanRun("default", "a"))
	a.jobsChanged()

	before := a.animationFrame()
	_, cmd := a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(1000)})

	if a.animationFrame() == before {
		t.Error("the frame did not advance")
	}
	if _, ok := testutil.MsgOf[animationTickMsg](cmd); !ok {
		t.Error("the chain was not renewed while work was running")
	}
}

func TestTheChainDiesWhenNothingRunsAndRestartsAfterwards(t *testing.T) {
	testutil.FastTimers(t, &animationFastInterval)
	view := &fakeView{}
	a := router(t, view)
	id := a.jobs.Start(scanRun("default", "a"))
	a.jobsChanged()

	a.jobs.Advance(id, "a", jobs.ItemDone, "")
	_, cmd := a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(1000)})

	if _, ok := testutil.MsgOf[animationTickMsg](cmd); ok {
		t.Error("the chain renewed itself with nothing left to animate")
	}
	if a.anim.ticking {
		t.Error("the router still believes a chain is alive")
	}
	a.jobs.Start(scanRun("default", "b"))
	if a.ensureTick() == nil {
		t.Error("a run started after the chain died got no chain")
	}
}

// Rule 122: the frame is bare, its rendering is not.
func TestTheFrameIsBareAndItsRenderingIsNot(t *testing.T) {
	view := &fakeView{}
	a := router(t, view)
	a.jobs.Start(scanRun("default", "a"))
	a.jobsChanged()

	frames := framesSeen(view)
	if len(frames) == 0 {
		t.Fatal("the view on screen was never handed a FrameMsg")
	}
	f := frames[len(frames)-1]
	if f.Frame == "" {
		t.Fatal("no spinner frame was carried")
	}
	if strings.Contains(f.Frame, "\x1b") {
		t.Errorf("Frame = %q carries an escape sequence; Rule 122", f.Frame)
	}
	if !strings.Contains(f.RenderedFrame, "\x1b") || !strings.Contains(f.RenderedFrame, f.Frame) {
		t.Errorf("RenderedFrame = %q, want the styled Frame %q (Rule 128)", f.RenderedFrame, f.Frame)
	}
}

// The blink phase is read off the message's own time, not the wall clock.
func TestTheFrameCarriesThePhaseOfTheTickTime(t *testing.T) {
	testutil.FastTimers(t, &animationFastInterval)
	view := &fakeView{}
	a := router(t, view)
	a.jobs.Start(scanRun("default", "a"))
	a.jobsChanged()

	for _, tt := range []struct {
		ms   int64
		want bool
	}{{1000, true}, {1500, false}, {2000, true}} {
		a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(tt.ms)})
		frames := framesSeen(view)
		if len(frames) == 0 {
			t.Fatalf("tick at %d ms delivered no FrameMsg", tt.ms)
		}
		if got := frames[len(frames)-1].Blink; got != tt.want {
			t.Errorf("tick at %d ms: Blink = %v, want %v", tt.ms, got, tt.want)
		}
	}
}

// A view entering the screen gets the snapshot, then the frame.
func TestAViewEnteringTheScreenGetsTheSnapshotAndTheFrame(t *testing.T) {
	ws := &fakeView{}
	a := router(t, &fakeView{})
	a.views[command.ViewWorkspaces] = ws
	a.jobs.Start(scanRun("default", "a"))
	a.anim.blinkOn = true

	a.switchView(command.ViewWorkspaces)

	changed, frame := -1, -1
	for i, msg := range ws.received {
		switch msg.(type) {
		case jobs.ChangedMsg:
			changed = i
		case jobs.FrameMsg:
			frame = i
		}
	}
	if changed < 0 || frame < 0 {
		t.Fatalf("entering view got ChangedMsg at %d and FrameMsg at %d, want both", changed, frame)
	}
	if changed > frame {
		t.Error("the FrameMsg came before the ChangedMsg")
	}
	if got := framesSeen(ws)[0]; got.Blink != a.anim.blinkOn {
		t.Errorf("entering FrameMsg.Blink = %v, want the router's %v", got.Blink, a.anim.blinkOn)
	}
}

// A registry change reaches every held view; the frame only the one on screen.
func TestARegistryChangeStillReachesEveryView(t *testing.T) {
	onScreen, other := &fakeView{}, &fakeView{}
